import pandas as pd


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"]
    cdc_events = inputs["cdc_events"]

    # --- Build initial state from target_state ---
    current_state = {}
    original_target_last_seq = {}
    had_row_ever = set()

    for _, row in target_state.iterrows():
        oid = row["order_id"]
        current_state[oid] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": row["last_seq"],
        }
        original_target_last_seq[oid] = row["last_seq"]
        had_row_ever.add(oid)

    original_target_exists = set(original_target_last_seq.keys())

    # --- Dedup events by seq (at-least-once delivery) ---
    events = cdc_events.drop_duplicates(subset=["seq"]).sort_values("seq", kind="mergesort")

    last_op_info = {}  # order_id -> (op, seq) -- only for EFFECTIVE events

    for _, ev in events.iterrows():
        seq = ev["seq"]
        oid = ev["order_id"]
        op = ev["op"]
        status = ev["status"]
        amount = ev["amount"]

        # Replay guard: only applies if the order had a row in the ORIGINAL target_state
        if oid in original_target_exists and seq <= original_target_last_seq[oid]:
            continue

        if op in ("I", "U"):
            # I/U is always effective: it either creates or updates the row.
            if oid in current_state:
                existing = current_state[oid]
                if op == "U" and pd.isna(amount):
                    new_amount = existing["amount"]
                else:
                    new_amount = amount
                current_state[oid] = {
                    "status": status,
                    "amount": new_amount,
                    "last_seq": seq,
                }
            else:
                current_state[oid] = {
                    "status": status,
                    "amount": amount,
                    "last_seq": seq,
                }
            had_row_ever.add(oid)
            last_op_info[oid] = (op, seq)
        elif op == "D":
            # D is only effective if the order currently has a row.
            # "A 'D' for a missing order does nothing" -- it is not recorded
            # as the "last applied event" for tombstone purposes.
            if oid in current_state:
                del current_state[oid]
                last_op_info[oid] = (op, seq)
            # else: true no-op, completely ignored

    # --- Build new_state ---
    if current_state:
        new_state_rows = []
        for oid, data in current_state.items():
            new_state_rows.append(
                {
                    "order_id": oid,
                    "status": data["status"],
                    "amount": data["amount"],
                    "last_seq": data["last_seq"],
                }
            )
        new_state = pd.DataFrame(new_state_rows)
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
        new_state["amount"] = new_state["amount"].astype("float64")
        new_state["status"] = new_state["status"].astype(object)
        new_state = new_state.sort_values("order_id").reset_index(drop=True)
    else:
        new_state = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "status": pd.Series(dtype="object"),
                "amount": pd.Series(dtype="float64"),
                "last_seq": pd.Series(dtype="int64"),
            }
        )

    # --- Build tombstones ---
    tomb_rows = []
    for oid in had_row_ever:
        info = last_op_info.get(oid)
        if info is not None and info[0] == "D":
            tomb_rows.append({"order_id": oid, "deleted_seq": info[1]})

    if tomb_rows:
        tombstones = pd.DataFrame(tomb_rows)
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")
        tombstones = tombstones.sort_values("order_id").reset_index(drop=True)
    else:
        tombstones = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "deleted_seq": pd.Series(dtype="int64"),
            }
        )

    return {"new_state": new_state, "tombstones": tombstones}
